# We have identified 8 old songs in the user's playlists with their song_ids.
# Next, we need to find which playlists contain these old songs.
# We have the user's playlists with their song_ids from previous steps.
# Let's create a mapping of playlist_id to song_ids for quick lookup.

playlist_songs_map = {}
for playlist in playlists:
    playlist_songs_map[playlist["playlist_id"]] = set(playlist["song_ids"])

# Create a set of old song IDs for quick membership test
old_song_ids_set = set(song["song_id"] for song in old_songs_found)

# Find playlists that contain old songs and the old songs in each playlist
playlists_with_old_songs = {}
for playlist_id, song_ids in playlist_songs_map.items():
    old_songs_in_playlist = song_ids.intersection(old_song_ids_set)
    if old_songs_in_playlist:
        playlists_with_old_songs[playlist_id] = old_songs_in_playlist

print(playlists_with_old_songs)  # playlist_id -> set of old song_ids in that playlist

