steps.code:
# The function is calling show_album with album_id None for some songs, causing no update for those.
# This means search_songs did not return any matching song with album_id for those queries.
# I will improve the get_release_month_for_song function to skip songs with album_id None and continue searching other results.
# Also, I will add a fallback to try searching with "song title artist" combined query if initial search fails.

def get_release_month_for_song(song_title, artist_names):
    queries = [song_title, f"{song_title} {artist_names}"]
    for query in queries:
        search_results = apis.spotify.search_songs(query=query, page_limit=5)
        for song in search_results:
            album_id = song.get('album_id')
            if not album_id:
                continue
            try:
                album = apis.spotify.show_album(album_id=album_id)
            except Exception:
                continue
            album_artist_names = [artist['name'] for artist in album['artists']]
            if any(artist_name.lower() in [a.lower() for a in album_artist_names] for artist_name in artist_names.split(',')):
                release_date = album['release_date']
                release_month = release_date[5:7]
                release_year = release_date[0:4]
                return f"{release_month}/{release_year}"
    return None

# Retry updating note content with improved function
updated_note_content = note_content

for song, artists in songs_to_update:
    try:
        release_month = get_release_month_for_song(song, artists)
    except Exception:
        release_month = None
    if release_month:
        old_line = f"- {song} BY {artists} RELEASED_AT TODO"
        new_line = f"- {song} BY {artists} RELEASED_AT {release_month}"
        updated_note_content = updated_note_content.replace(old_line, new_line)

print(updated_note_content)  # verify updated content before saving back to simple_note API

